    """Stop where the rider is waiting."""
    direction: Direction
    """Travel direction. Turn 1 supports direction 1 only."""
    origin: Origin
    """Origin of the rider. 'train' means arrival from a Metro train (requires train_trip_id)."""
    destination_stop_id: Annotated[str, Field(min_length=1)]
    """Stop the rider wants to travel to."""
    train_trip_id: Annotated[str | None, Field(min_length=1)] = None
    """Metro train trip identifier. Required when origin is 'train'; forbidden otherwise."""

    @model_validator(mode="after")
    def _validate_train_trip_id_conditional(self) -> "RiderArrivalPayload":
        """Enforce the JSON Schema allOf if/then/else conditional:
        - origin == 'train'  → train_trip_id must be present and non-empty
        - origin == 'street' → train_trip_id must be absent (None)
        """
        if self.origin == Origin.train:
            if not self.train_trip_id:
                raise ValueError(
                    "train_trip_id is required when origin is 'train'"
                )
        else:
            if self.train_trip_id is not None:
                raise ValueError(
                    "train_trip_id is forbidden when origin is not 'train'"
                )
        return self


